  {
    "resource": "aws_ebs_volume.web_host_storage",
    "issue": "EBS volume encryption not enabled",
    "risk": "Data stored on the volume may be exposed if the underlying storage is accessed improperly or snapshots/copies are shared, increasing the risk of sensitive data disclosure.",
    "remediation": "Set the `encrypted = true` attribute on `aws_ebs_volume.web_host_storage`. Optionally add `kms_key_id` to use a customer-managed KMS key."
  },
  {
    "resource": "aws_ebs_snapshot.example_snapshot",
    "issue": "Snapshot created from unencrypted volume",
    "risk": "The snapshot inherits the lack of encryption from the source volume, which can expose backed-up data if accessed or shared improperly.",
    "remediation": "Encrypt the source volume by setting `aws_ebs_volume.web_host_storage.encrypted = true` and recreate the snapshot. If creating a separate encrypted copy, use an encrypted snapshot/copy workflow with a KMS key."
  },
  {
    "resource": "aws_security_group.web-node",
